import{_ as e,o as a,c as o,a2 as r}from"./chunks/framework.BEUshCVJ.js";const p=JSON.parse('{"title":"导出诊断信息","description":"","frontmatter":{},"headers":[],"relativePath":"zh/troubleshooting/diagnostics.md","filePath":"zh/troubleshooting/diagnostics.md","lastUpdated":1793229750000}'),i={name:"zh/troubleshooting/diagnostics.md"};function l(s,t,d,n,h,c){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="导出诊断信息" tabindex="-1">导出诊断信息 <a class="header-anchor" href="#导出诊断信息" aria-label="Permalink to &quot;导出诊断信息&quot;">​</a></h1><p>本页介绍如何收集排查问题所需的信息，以及导出文件里包含什么。</p><h2 id="导出文件" tabindex="-1">导出文件 <a class="header-anchor" href="#导出文件" aria-label="Permalink to &quot;导出文件&quot;">​</a></h2><ol><li>右键 MeetCue 托盘图标，选择 <strong>导出诊断信息…</strong>；或打开 <strong>设置 › 诊断</strong>，点击 <strong>导出…</strong>。</li><li>点击 <strong>查看将包含的内容</strong> 查看文件列表。</li><li>选择 zip 文件的保存位置。</li></ol><h2 id="包含的内容" tabindex="-1">包含的内容 <a class="header-anchor" href="#包含的内容" aria-label="Permalink to &quot;包含的内容&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>日志</td><td>最近三天的 MeetCue 日志文件。API 密钥和令牌已脱敏。</td></tr><tr><td>设置</td><td>去掉会前资料正文的 <code>settings.json</code>。这个文件里本来就没有密钥。</td></tr><tr><td>延迟历史</td><td>延迟探测生成的 <code>latency-history.json</code>。</td></tr><tr><td>系统信息</td><td>Windows 版本、MeetCue 版本、音频设备名称与采样率。</td></tr></tbody></table><h2 id="不会包含的内容" tabindex="-1">不会包含的内容 <a class="header-anchor" href="#不会包含的内容" aria-label="Permalink to &quot;不会包含的内容&quot;">​</a></h2><ul><li>API 密钥和访问令牌。</li><li>会议转写。除非你开启了调试日志，日志中不含转写；即使开启了，导出时也会排除。</li><li>会前资料和练习记录。</li></ul><h2 id="运行自检" tabindex="-1">运行自检 <a class="header-anchor" href="#运行自检" aria-label="Permalink to &quot;运行自检&quot;">​</a></h2><p><code>MeetCue.exe --self-test</code> 会检查那些只能在你的电脑上测试的部分，并输出一份简短报告：</p><ul><li>系统声音采集能收到测试音（请把扬声器静音或戴上耳机）；</li><li>麦克风电平；</li><li>所有快捷键注册成功；</li><li>面板不会出现在截图中；</li><li>已配置密钥时，各供应商能正常响应。</li></ul><p>把报告复制到 Issue 中。</p><h2 id="报告问题" tabindex="-1">报告问题 <a class="header-anchor" href="#报告问题" aria-label="Permalink to &quot;报告问题&quot;">​</a></h2><p><a href="https://github.com/Amazingkenneth/meetcue/issues/new?template=bug.yml" target="_blank" rel="noreferrer">提交 Issue</a>。表单会要求填写错误码、MeetCue 版本（<code>MeetCue.exe --version</code>）和出现问题的步骤，并附上诊断 zip 文件。</p><h2 id="调试日志" tabindex="-1">调试日志 <a class="header-anchor" href="#调试日志" aria-label="Permalink to &quot;调试日志&quot;">​</a></h2><p>如有需要，打开 <strong>设置 › 诊断 › 调试日志</strong>，重现问题后再次导出。调试日志会把转写写入你电脑上的日志，排查完成后请关闭。</p>',16)])])}const b=e(i,[["render",l]]);export{p as __pageData,b as default};
